import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Users } from 'lucide-react';
import { getApiBaseUrl } from '../utils/api';
import LocationAutocomplete from './LocationAutocomplete';

const sports = [
  { value: 'baseball', label: 'Baseball', emoji: '⚾' },
  { value: 'basketball', label: 'Basketball', emoji: '🏀' },
  { value: 'soccer', label: 'Soccer', emoji: '⚽' },
  { value: 'softball', label: 'Softball', emoji: '🥎' },
];

const CreateGame: React.FC = () => {
  const [title, setTitle] = useState('');
  const [sport, setSport] = useState('');
  const [location, setLocation] = useState('');
  const [locationData, setLocationData] = useState<any>(null);
  const [maxPlayers, setMaxPlayers] = useState(10);
  const [gameDate, setGameDate] = useState('');
  const [gameTime, setGameTime] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [level, setLevel] = useState('A');
  const [isCasual, setIsCasual] = useState(false);
  const [isPrivate, setIsPrivate] = useState(false);
  const [minAge, setMinAge] = useState(0);
  const [isMoneyGame, setIsMoneyGame] = useState(false);
  const [entryFee, setEntryFee] = useState(0);

  const navigate = useNavigate();

  // Generate date options for the next 30 days
  const getDateOptions = () => {
    const options = [];
    const today = new Date();

    for (let i = 0; i < 30; i++) {
      const date = new Date(today);
      date.setDate(today.getDate() + i);
      const dateString = date.toISOString().split('T')[0];
      const displayDate = date.toLocaleDateString('en-US', { 
        weekday: 'short', 
        month: 'short', 
        day: 'numeric' 
      });
      options.push({ value: dateString, label: displayDate });
    }
    return options;
  };

  // Generate time options in 30-minute intervals
  const getTimeOptions = () => {
    const options = [];
    for (let hour = 6; hour <= 22; hour++) {
      for (let minute = 0; minute < 60; minute += 30) {
        const timeString = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
        const displayTime = new Date(`2000-01-01T${timeString}`).toLocaleTimeString('en-US', {
          hour: 'numeric',
          minute: '2-digit',
          hour12: true
        });
        options.push({ value: timeString, label: displayTime });
      }
    }
    return options;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    if (!gameDate || !gameTime || !level) {
      setError('Game date, time and level are required');
      setLoading(false);
      return;
    }

    // Combine date and time into ISO string
    const combinedDateTime = `${gameDate}T${gameTime}:00`;

    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/games`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          title,
          sport,
          location,
          locationData,
          maxPlayers: Number(maxPlayers),
          gameTime: combinedDateTime,
          level,
          isCasual,
          isPrivate,
          minAge: Number(minAge),
          isMoneyGame,
          entryFee: Number(entryFee)
        })
      });

      if (response.ok) {
        const data = await response.json();
        if (data.id) {
          // Show success message briefly before navigating
          setError(''); // Clear any previous errors
          setTimeout(() => {
            navigate(`/game/${data.id}`);
          }, 100);
        } else {
          console.error('No game ID in response:', data);
          navigate('/');
        }
      } else {
        const error = await response.json();
        setError(error.error || 'Failed to create game');
      }
    } catch (error) {
      console.error('Error creating game:', error);
      setError('Failed to create game');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900">Create a Pickup Game</h1>
        <p className="mt-2 text-gray-600">Set up a new game and invite players to join</p>
      </div>

      <div className="bg-white rounded-lg shadow-md p-6">
        {error && (
          <div className="mb-6 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label htmlFor="title" className="block text-sm font-medium text-gray-700 mb-2">
              Game Title
            </label>
            <input
              type="text"
              id="title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              placeholder="e.g., Weekend Basketball at Central Park"
            />
          </div>

          <div>
            <label htmlFor="sport" className="block text-sm font-medium text-gray-700 mb-2">
              Sport
            </label>
            <select
              id="sport"
              value={sport}
              onChange={(e) => setSport(e.target.value)}
              required
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            >
              <option value="">Select a sport</option>
              {sports.map((sportOption) => (
                <option key={sportOption.value} value={sportOption.value}>
                  {sportOption.emoji} {sportOption.label}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label htmlFor="location" className="block text-sm font-medium text-gray-700 mb-2">
              Location
            </label>
            <LocationAutocomplete
              value={location}
              onChange={(newLocation, data) => {
                setLocation(newLocation);
                setLocationData(data);
              }}
              placeholder="Search for a location..."
              required
            />
          </div>

          <div>
            <label htmlFor="maxPlayers" className="block text-sm font-medium text-gray-700 mb-2">
              Maximum Players
            </label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Users className="h-5 w-5 text-gray-400" />
              </div>
              <input
                type="number"
                id="maxPlayers"
                value={maxPlayers}
                onChange={(e) => setMaxPlayers(parseInt(e.target.value))}
                min="2"
                max="50"
                required
                className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              />
            </div>
            <p className="mt-1 text-sm text-gray-500">Choose between 2-50 players</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label htmlFor="gameDate" className="block text-sm font-medium text-gray-700 mb-2">
                Game Date
              </label>
              <select
                id="gameDate"
                value={gameDate}
                onChange={(e) => setGameDate(e.target.value)}
                required
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="">Select a date</option>
                {getDateOptions().map((dateOption) => (
                  <option key={dateOption.value} value={dateOption.value}>
                    {dateOption.label}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label htmlFor="gameTime" className="block text-sm font-medium text-gray-700 mb-2">
                Game Time
              </label>
              <select
                id="gameTime"
                value={gameTime}
                onChange={(e) => setGameTime(e.target.value)}
                required
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="">Select a time</option>
                {getTimeOptions().map((timeOption) => (
                  <option key={timeOption.value} value={timeOption.value}>
                    {timeOption.label}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label htmlFor="level" className="block text-sm font-medium text-gray-700 mb-2">
                Skill Level
              </label>
              <select
                id="level"
                value={level}
                onChange={e => setLevel(e.target.value)}
                required
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="A">A (Advanced)</option>
                <option value="B">B (Intermediate)</option>
                <option value="C">C (Recreational)</option>
              </select>
            </div>

            <div>
              <label htmlFor="minAge" className="block text-sm font-medium text-gray-700 mb-2">
                Minimum Age (Optional)
              </label>
              <input
                type="number"
                id="minAge"
                value={minAge}
                onChange={e => setMinAge(parseInt(e.target.value) || 0)}
                min="0"
                max="100"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="No minimum age"
              />
              <p className="mt-1 text-sm text-gray-500">Leave as 0 for no age restriction</p>
            </div>
          </div>
          <div className="space-y-3">
            <div className="flex items-center">
              <input
                id="isCasual"
                type="checkbox"
                checked={isCasual}
                onChange={e => setIsCasual(e.target.checked)}
                className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              />
              <label htmlFor="isCasual" className="ml-2 block text-sm text-gray-700">
                Casual Game (does not count towards record)
              </label>
            </div>

            <div className="flex items-center">
              <input
                id="isPrivate"
                type="checkbox"
                checked={isPrivate}
                onChange={e => setIsPrivate(e.target.checked)}
                className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              />
              <label htmlFor="isPrivate" className="ml-2 block text-sm text-gray-700">
                Private Game (only accessible via direct link)
              </label>
            </div>

            <div className="flex items-center">
              <input
                id="isMoneyGame"
                type="checkbox"
                checked={isMoneyGame}
                onChange={e => setIsMoneyGame(e.target.checked)}
                className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              />
              <label htmlFor="isMoneyGame" className="ml-2 block text-sm text-gray-700">
                Money Game (entry fee required)
              </label>
            </div>
          </div>

          {isMoneyGame && (
            <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
              <h3 className="text-sm font-medium text-yellow-800 mb-3">Money Game Settings</h3>
              <div className="space-y-3">
                <div>
                  <label htmlFor="entryFee" className="block text-sm font-medium text-gray-700 mb-2">
                    Entry Fee per Player ($)
                  </label>
                  <input
                    type="number"
                    id="entryFee"
                    value={entryFee}
                    onChange={e => setEntryFee(parseFloat(e.target.value) || 0)}
                    min="0"
                    step="0.01"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    placeholder="0.00"
                  />
                </div>
                <div className="bg-white rounded-md p-3 border border-yellow-200">
                  <div className="text-sm text-gray-600">
                    <div className="flex justify-between mb-1">
                      <span>Total Pot:</span>
                      <span className="font-semibold text-green-600">${(entryFee * maxPlayers).toFixed(2)}</span>
                    </div>
                    <div className="flex justify-between mb-1">
                      <span>Winning Team Gets:</span>
                      <span className="font-semibold text-green-600">${(entryFee * maxPlayers).toFixed(2)}</span>
                    </div>
                    <div className="text-xs text-gray-500 mt-2">
                      * 50/50 odds - winning team splits the entire pot
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          <div className="flex items-center justify-end space-x-4 pt-6">
            <button
              type="button"
              onClick={() => navigate('/')}
              className="px-4 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading}
              className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? 'Creating...' : 'Create Game'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CreateGame;
